import { createElement } from 'react';
import type { HTMLAttributes } from 'react';

type RichTextTag = 'span' | 'div' | 'h2' | 'p' | 'small' | 'strong' | 'b';

interface RichTextProps extends Omit<HTMLAttributes<HTMLElement>, 'children' | 'dangerouslySetInnerHTML'> {
  /**
   * TRUSTED markup only.
   *
   * Trust boundary: this component injects `html` verbatim. It must only receive strings generated by the
   * domain (`Question.prompt`, `Question.vis`, `hint`, `why`, choice option labels and the markup builders in
   * `domain/exercises`), which are assembled from numbers and generator-controlled text. Never pass user input
   * (child names, emails, anything typed or loaded from storage) to it; render that as normal React children,
   * which React escapes.
   */
  html: string;
  as?: RichTextTag;
}

export function RichText({ html, as = 'span', ...rest }: RichTextProps) {
  return createElement(as, { ...rest, dangerouslySetInnerHTML: { __html: html } });
}
